CREATE TABLE IF NOT EXISTS project_source_assets (asset_id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects(project_id), operation_id text NOT NULL, role text NOT NULL CHECK(role IN ('visual_reference','official_logo','product_image','brand_photo','graphic_asset')), original_filename text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('image/jpeg','image/png','image/webp')), byte_size bigint NOT NULL CHECK(byte_size > 0), width integer CHECK(width > 0), height integer CHECK(height > 0), checksum text NOT NULL CHECK(checksum ~ '^[a-f0-9]{64}$'), backing_ref text NOT NULL, status text NOT NULL CHECK(status IN ('available','invalid','unavailable','superseded','removed')), supersedes_asset_id text REFERENCES project_source_assets(asset_id), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(project_id, operation_id));
CREATE INDEX IF NOT EXISTS source_assets_project_idx ON project_source_assets(project_id);
CREATE INDEX IF NOT EXISTS source_assets_project_role_idx ON project_source_assets(project_id, role);
CREATE INDEX IF NOT EXISTS source_assets_project_created_idx ON project_source_assets(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS source_assets_project_checksum_idx ON project_source_assets(project_id, checksum);
